`timescale 1ns/1ps
// Teaching trace: capture PRE-edge and POST-NBA values from the unchanged RTL.
// Not part of the functional regression; vectors are generated by build_timing_demo.py.
module tb_timing_capture;
  reg clk=0;
  always #3.333 clk=~clk;
  reg rst_n=0,cmd_valid=0,cmd_read=0,rsp_ready=0;
  reg [31:0] cmd_addr=0,cmd_wdata=0;
  reg [3:0] cmd_wmask=15;
  wire cmd_ready,rsp_valid,rsp_err,irq;
  wire [31:0] rsp_rdata;
  ffn_accel dut(
    .clk(clk),.rst_n(rst_n),.i_icb_cmd_valid(cmd_valid),.o_icb_cmd_ready(cmd_ready),
    .i_icb_cmd_read(cmd_read),.i_icb_cmd_addr(cmd_addr),.i_icb_cmd_wdata(cmd_wdata),
    .i_icb_cmd_wmask(cmd_wmask),.o_icb_rsp_valid(rsp_valid),.i_icb_rsp_ready(rsp_ready),
    .o_icb_rsp_rdata(rsp_rdata),.o_icb_rsp_err(rsp_err),.o_irq(irq)
  );
  reg [15:0] xv[0:6335],wv[0:16383],bv[0:255],yv[0:25343];
  integer fd,scenario=-1,edge_number=0;
  string folder="build/timing",path;
  reg capture;
  reg [31:0] readback;
  integer guard;

  task dump_snapshot;
    begin
      // All values are strings to preserve X in JSON; the Python packer maps X to null.
      $fwrite(fd,"{\"rst_n\":\"%0d\",\"cmd_valid\":\"%0d\",\"cmd_ready\":\"%0d\",\"cmd_read\":\"%0d\",\"cmd_addr\":\"%0d\",\"cmd_wdata\":\"%0d\",\"rsp_valid\":\"%0d\",\"rsp_ready\":\"%0d\",\"rsp_err\":\"%0d\",\"rsp_rdata\":\"%0d\",",rst_n,cmd_valid,cmd_ready,cmd_read,cmd_addr,cmd_wdata,rsp_valid,rsp_ready,rsp_err,rsp_rdata);
      $fwrite(fd,"\"host_state\":\"%0d\",\"state\":\"%0d\",\"busy\":\"%0d\",\"done\":\"%0d\",\"irq\":\"%0d\",\"cycles\":\"%0d\",\"row\":\"%0d\",\"group\":\"%0d\",",dut.host_state,dut.state,dut.busy,dut.done,irq,dut.cycle_count,dut.row_index,dut.group_index);
      $fwrite(fd,"\"bias_issue\":\"%0d\",\"bias_valid\":\"%0d\",\"bias_lane\":\"%0d\",\"b_en\":\"%0d\",\"b_addr\":\"%0d\",\"b_rdata\":\"%0d\",",dut.bias_issue,dut.bias_valid,dut.bias_lane_d,dut.b_en,dut.b_addr,$signed(dut.b_rdata));
      $fwrite(fd,"\"mac_issue\":\"%0d\",\"read_valid\":\"%0d\",\"product_valid\":\"%0d\",\"product_last\":\"%0d\",\"x_en\":\"%0d\",\"x_we\":\"%0d\",\"x_addr\":\"%0d\",\"x_rdata\":\"%0d\",\"w0_rdata\":\"%0d\",",dut.mac_issue,dut.mac_read_valid,dut.product_valid,dut.product_last,dut.x_en,dut.x_we,dut.x_addr,$signed(dut.x_rdata),$signed(dut.w_rdata[0]));
      $fwrite(fd,"\"product0\":\"%0d\",\"acc0\":\"%0d\",\"out0\":\"%0d\",\"write_lane\":\"%0d\",\"y_en\":\"%0d\",\"y_we\":\"%0d\",\"y_addr\":\"%0d\",\"y_wdata\":\"%0d\"}",dut.product[0],dut.accumulator[0],$signed(dut.output_buffer[0]),dut.write_lane,dut.y_en,dut.y_we,dut.y_addr,$signed(dut.y_wdata));
    end
  endtask
  always @(posedge clk) begin
    edge_number=edge_number+1;
    capture=(scenario>=0) && (scenario!=3 || dut.cycle_count<102) &&
                             (scenario!=4 || dut.cycle_count>=158299);
    if(capture) begin
      $fwrite(fd,"{\"scenario\":%0d,\"edge\":%0d,\"time_ps\":%0t,\"pre\":",scenario,edge_number,$realtime);
      dump_snapshot();
      #0.001;
      $fwrite(fd,",\"post\":");dump_snapshot();$fwrite(fd,"}\n");
    end
  end
  task automatic bus(input bit rd,input reg[31:0] addr,input reg[31:0] data,
                     input integer stall,input bit want_error);
    integer n;
    begin
      @(negedge clk);cmd_valid=1;cmd_read=rd;cmd_addr=addr;cmd_wdata=data;rsp_ready=0;
      while(!cmd_ready)@(negedge clk);
      @(posedge clk);@(negedge clk);cmd_valid=0;
      while(!rsp_valid)@(negedge clk);
      repeat(stall)@(negedge clk);
      if(rsp_err!==want_error)$fatal(1,"Unexpected response error");
      readback=rsp_rdata;rsp_ready=1;
      @(posedge clk);@(negedge clk);rsp_ready=0;
    end
  endtask
  initial begin
    if($value$plusargs("FOLDER=%s",folder))begin end
    fd=$fopen($sformatf("%s/trace.jsonl",folder),"w");
    if(!fd)$fatal(1,"Cannot open capture output");
    $readmemh($sformatf("%s/layer_03_x.hex",folder),xv);
    $readmemh($sformatf("%s/layer_03_w.hex",folder),wv);
    $readmemh($sformatf("%s/layer_03_b.hex",folder),bv);
    $readmemh($sformatf("%s/layer_03_y.hex",folder),yv);
    repeat(4)@(negedge clk);rst_n=1;repeat(2)@(negedge clk);
    // Load the complete actual shapes through the external bus, with capture off.
    for(integer i=0;i<6336;i=i+1)bus(0,32'h10000+4*i,{16'd0,xv[i]},0,0);
    for(integer i=0;i<16384;i=i+1)bus(0,32'h20000+4*i,{16'd0,wv[i]},0,0);
    for(integer i=0;i<256;i=i+1)bus(0,32'h30000+4*i,{16'd0,bv[i]},0,0);
    scenario=0;repeat(2)@(negedge clk);
    bus(0,32'h10000,{16'd0,xv[0]},0,0);repeat(2)@(negedge clk);
    scenario=1;repeat(2)@(negedge clk);
    bus(1,32'h10000,0,0,0);
    if(readback!==32'hfffffe00)$fatal(1,"Expected sign-extended -512");
    repeat(2)@(negedge clk);
    scenario=2;repeat(2)@(negedge clk);
    bus(1,32'h10000,0,3,0);repeat(2)@(negedge clk);
    scenario=3;repeat(2)@(negedge clk);
    bus(0,0,1,0,0);
    while(dut.cycle_count<101)@(negedge clk);
    scenario=5;repeat(2)@(negedge clk);
    bus(1,32'h40000,0,1,1);
    bus(1,4,0,0,0); // BUSY is not a blanket bus stall; status reads still succeed.
    repeat(2)@(negedge clk);scenario=-1;
    while(dut.cycle_count<158299)@(negedge clk);
    scenario=4;
    while(!irq)@(negedge clk);
    repeat(2)@(negedge clk);bus(1,32'h40000,0,0,0);
    if(readback!=={{16{yv[0][15]}},yv[0]})$fatal(1,"First output mismatch");
    bus(0,0,2,0,0);repeat(2)@(negedge clk);
    scenario=-1;
    // Restart without clearing SRAM, then asynchronously abort on a falling edge.
    bus(0,0,1,0,0);repeat(20)@(negedge clk);
    scenario=6;repeat(3)@(negedge clk);
    rst_n=0;cmd_valid=0;rsp_ready=0;repeat(3)@(negedge clk);
    rst_n=1;repeat(3)@(negedge clk);bus(1,4,0,0,0);repeat(2)@(negedge clk);
    scenario=-1;$fclose(fd);
    $display("TIMING TRACE PASS: unchanged RTL, full-size task, seven scenarios");
    $finish;
  end
  initial begin #5000000;$fatal(1,"Timing capture watchdog");end
endmodule
